 "content": "def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    # A full-width separator divides a top bar from matching-color markers
    # on the last row. Extend the selected columns down to the separator in 4.
    width = len(grid[0])
    top_color = grid[0][0]
    if not all(len(row) == width for row in grid):
        return out
    separator = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    if separator is None:
        return out
    for c in range(width):
        if grid[0][c] == top_color and grid[-1][c] == top_color:
            for r in range(1, separator):
                out[r][c] = 4
    return out
